// Rule L3b, and where sharing ends: `uv` is written between the two selections, so they are two calls.
/// @asset Path(Game, "Functions/MF_MgSplit2")
extern void MF_MgSplit2(float2 UV, out float3 Head, out float Tail);

/// @name DreamShaderTests/Migrate/M_MgSelectInvalidated
export void M_MgSelectInvalidated(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float2 uv = UE.TexCoord(Index = 0);
    float3 MF_MgSplit2_Head;
    float MF_MgSplit2_Tail;
    MF_MgSplit2(uv, Head = MF_MgSplit2_Head, Tail = MF_MgSplit2_Tail);
    Color = MF_MgSplit2_Head;
    uv = uv * 2.0;
    float3 MF_MgSplit2_Head_2;
    float MF_MgSplit2_Tail_2;
    MF_MgSplit2(uv, Head = MF_MgSplit2_Head_2, Tail = MF_MgSplit2_Tail_2);
    Alpha = MF_MgSplit2_Tail_2;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
